package com.personal.routemanager;
import static org.junit.Assert.*;
import android.content.Context;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class NotesStoreTest {
 private Context context;private NotesStore store;
 @Before public void reset(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("route_manager",0).edit().clear().commit();store=new NotesStore(context);}
 private JSONObject state()throws Exception{JSONObject routes=new JSONObject();for(String route:new String[]{"g2","g3","g4","g5","g6"})routes.put(route,new JSONObject().put("stops",new JSONArray()).put("notes",new JSONArray()));return new JSONObject().put("version",1).put("current","g2").put("routes",routes).put("appearance",new JSONObject().put("top","#203747").put("bottom","#5a5c61").put("text","#ffffff").put("accent","#ffffff").put("gradient",true).put("size","normal"));}
 @Test public void freshStoreIsEmptyWithoutInventedStops(){assertEquals("{}",store.read());}
 @Test public void allFiveRoutesAndMultipleStopNotesSurviveReload()throws Exception{JSONObject data=state(),page=data.getJSONObject("routes").getJSONObject("g2");page.getJSONArray("stops").put(new JSONObject().put("id","a").put("name","First stop").put("cadence","weekly")).put(new JSONObject().put("id","b").put("name","Second stop").put("cadence","biweekly"));page.getJSONArray("notes").put(new JSONObject().put("id","note").put("body","Keep both stop associations").put("stops",new JSONArray().put("a").put("b")).put("createdAt",1).put("updatedAt",2));store.write(data.toString());JSONObject loaded=new JSONObject(new NotesStore(context).read());assertEquals(5,loaded.getJSONObject("routes").length());assertEquals(2,loaded.getJSONObject("routes").getJSONObject("g2").getJSONArray("notes").getJSONObject(0).getJSONArray("stops").length());assertEquals(0,loaded.getJSONObject("routes").getJSONObject("g3").getJSONArray("notes").length());}
 @Test public void invalidSaveCannotReplaceExistingNotes()throws Exception{String before=state().toString();store.write(before);for(String raw:new String[]{"broken","[]","{}",new JSONObject(before).put("version",2).toString()}){try{store.write(raw);fail();}catch(IllegalArgumentException expected){}assertEquals(before,store.read());}}
 @Test public void unknownStopAndDuplicateNamesAreRejected()throws Exception{JSONObject data=state(),page=data.getJSONObject("routes").getJSONObject("g2");page.getJSONArray("stops").put(new JSONObject().put("id","a").put("name","Customer").put("cadence","weekly")).put(new JSONObject().put("id","b").put("name","customer").put("cadence","biweekly"));try{store.write(data.toString());fail();}catch(IllegalArgumentException expected){}page.getJSONArray("stops").remove(1);page.getJSONArray("notes").put(new JSONObject().put("id","n").put("body","Text").put("stops",new JSONArray().put("missing")).put("createdAt",1).put("updatedAt",1));try{store.write(data.toString());fail();}catch(IllegalArgumentException expected){}assertEquals("{}",store.read());}
 @Test public void notesDoNotShareTheTasksStore()throws Exception{context.getSharedPreferences("reference_state",0).edit().putString("state","Tasks data").commit();store.write(state().toString());assertEquals("Tasks data",context.getSharedPreferences("reference_state",0).getString("state",null));}
 @Test public void invalidStoredDataIsRetainedInsteadOfReset()throws Exception{context.getSharedPreferences("route_manager",0).edit().putString("state","corrupt").commit();try{store.read();fail();}catch(IllegalArgumentException expected){}assertEquals("corrupt",context.getSharedPreferences("route_manager",0).getString("state",null));}
 @Test public void monthlyAndMatchingNamesOnDifferentRoutesStayIndependent()throws Exception{
  JSONObject data=state(),routes=data.getJSONObject("routes");routes.getJSONObject("g2").getJSONArray("stops").put(new JSONObject().put("id","mon").put("name","Shared customer").put("cadence","monthly"));routes.getJSONObject("g3").getJSONArray("stops").put(new JSONObject().put("id","tue").put("name","Shared customer").put("cadence","weekly"));store.write(data.toString());JSONObject saved=new JSONObject(new NotesStore(context).read()).getJSONObject("routes");assertEquals("monthly",saved.getJSONObject("g2").getJSONArray("stops").getJSONObject(0).getString("cadence"));assertEquals("weekly",saved.getJSONObject("g3").getJSONArray("stops").getJSONObject(0).getString("cadence"));
  saved.getJSONObject("g2").getJSONArray("stops").getJSONObject(0).put("cadence","biweekly");data.put("routes",saved);store.write(data.toString());assertEquals("weekly",new JSONObject(store.read()).getJSONObject("routes").getJSONObject("g3").getJSONArray("stops").getJSONObject(0).getString("cadence"));
 }
 @Test public void invalidCadenceDoesNotOverwriteMonthlyStops()throws Exception{JSONObject data=state(),stop=new JSONObject().put("id","monthly").put("name","Monthly customer").put("cadence","monthly");data.getJSONObject("routes").getJSONObject("g2").getJSONArray("stops").put(stop);store.write(data.toString());String before=store.read();stop.put("cadence","unknown");try{store.write(data.toString());fail();}catch(IllegalArgumentException expected){}assertEquals(before,store.read());}
 @Test public void sameNamedAccountsRetainSeparateIdsAndLeadingZeros()throws Exception{JSONObject data=state(),page=data.getJSONObject("routes").getJSONObject("g2");page.getJSONArray("stops").put(new JSONObject().put("id","one").put("name","Same Customer").put("accountNumber","00123").put("cadence","weekly")).put(new JSONObject().put("id","two").put("name","Same Customer").put("accountNumber","00456").put("cadence","monthly"));page.getJSONArray("notes").put(new JSONObject().put("id","n").put("body","Only the second account").put("stops",new JSONArray().put("two")).put("createdAt",1).put("updatedAt",1));store.write(data.toString());JSONObject saved=new JSONObject(new NotesStore(context).read()).getJSONObject("routes").getJSONObject("g2");assertEquals("00123",saved.getJSONArray("stops").getJSONObject(0).getString("accountNumber"));assertEquals("two",saved.getJSONArray("notes").getJSONObject(0).getJSONArray("stops").getString(0));String before=store.read();page.getJSONArray("stops").getJSONObject(1).put("accountNumber","00123");try{store.write(data.toString());fail();}catch(IllegalArgumentException expected){}assertEquals(before,store.read());}
 @Test public void malformedAccountAndRouteOffsetsDoNotReplaceSavedData()throws Exception{JSONObject data=state();store.write(data.toString());String before=store.read();for(Object offset:new Object[]{-1,3,1.5,"1",JSONObject.NULL}){data.put("routeOffset",offset);try{store.write(data.toString());fail();}catch(IllegalArgumentException expected){}assertEquals(before,store.read());}data.remove("routeOffset");JSONObject stop=new JSONObject().put("id","a").put("name","Account").put("cadence","weekly");data.getJSONObject("routes").getJSONObject("g2").getJSONArray("stops").put(stop);for(Object number:new Object[]{123,JSONObject.NULL,"x".repeat(81),"bad\naccount"}){stop.put("accountNumber",number);try{store.write(data.toString());fail();}catch(IllegalArgumentException expected){}assertEquals(before,store.read());}}
 @Test public void weekdayOffsetSurvivesReloadWithoutChangingRoutes()throws Exception{JSONObject data=state();data.put("routeOffset",2);store.write(data.toString());assertEquals(2,new JSONObject(new NotesStore(context).read()).getInt("routeOffset"));assertEquals(5,new JSONObject(store.read()).getJSONObject("routes").length());}
 @Test public void inProgressSurvivesReloadAndRejectsInvalidFlags()throws Exception{JSONObject data=state(),note=new JSONObject().put("id","active").put("body","Working on this").put("stops",new JSONArray()).put("createdAt",1).put("updatedAt",2).put("inProgress",true);data.getJSONObject("routes").getJSONObject("g2").getJSONArray("notes").put(note);store.write(data.toString());assertTrue(new JSONObject(new NotesStore(context).read()).getJSONObject("routes").getJSONObject("g2").getJSONArray("notes").getJSONObject(0).getBoolean("inProgress"));String before=store.read();note.put("inProgress","true");try{store.write(data.toString());fail();}catch(IllegalArgumentException expected){}assertEquals(before,store.read());note.put("inProgress",false);store.write(data.toString());assertFalse(new JSONObject(store.read()).getJSONObject("routes").getJSONObject("g2").getJSONArray("notes").getJSONObject(0).getBoolean("inProgress"));}

}
